import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"Birthday Party Invitation","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/01-birthday-invitation.md","filePath":"en/more/maltese/practice/emails/01-birthday-invitation.md"}'),r={name:"en/more/maltese/practice/emails/01-birthday-invitation.md"},o=d('<h1 id="birthday-party-invitation" tabindex="-1">Birthday Party Invitation <a class="header-anchor" href="#birthday-party-invitation" aria-label="Permalink to &quot;Birthday Party Invitation&quot;">​</a></h1><p><strong>Scenario:</strong> Anna invites her friend Mark to her birthday party.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand (From):</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data (Date):</strong> 10 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Stedina għall-festa ta&#39; għeluq snini</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 10 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Stedina għall-festa ta&#39; għeluq snini</p><p>Għażiż Mark,</p><p>Nispera li inti tajjeb.</p><p>Nixtieq nistedinkom għall-festa ta&#39; għeluq snini nhar is-Sibt.</p><p>Il-festa se tibda fis-sebgħa ta&#39; filgħaxija.</p><p>Se niltaqgħu d-dar tiegħi f&#39;Valletta.</p><p>Ikun hemm ikel, mużika u kejk.</p><p>Tista&#39; ġġib lil xi ħadd miegħek jekk trid.</p><p>Jekk jogħġbok, għidli jekk ġej.</p><p>Nistenna bil-ħerqa li niċċelebraw flimkien.</p><p>Tislijiet, Anna</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>email address</td><td>Recipient&#39;s (Mark&#39;s) email</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>Translation:</strong> From: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>email address</td><td>Sender&#39;s (Anna&#39;s) email</td></tr></tbody></table><p><strong>Malti:</strong> Data: 10 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 10 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>10</td><td>ten</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għall-festa ta&#39; għeluq snini</p><p><strong>Translation:</strong> Subject: Birthday Party Invitation</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Stedina</td><td>invitation</td><td>Feminine noun</td></tr><tr><td>għall-festa</td><td>to the party</td><td>Contracted <code>għal</code> + <code>il-festa</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>għeluq</td><td>celebration; anniversary</td><td>In <code>għeluq snini</code>, it refers to a birthday</td></tr><tr><td>snini</td><td>my years; my age</td><td><code>snin</code> &quot;years&quot; + first-person possessive <code>-i</code></td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Mark,</p><p><strong>Translation:</strong> Dear Mark,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form used to address a man</td></tr><tr><td>Mark</td><td>Mark</td><td>Name</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li inti tajjeb.</p><p><strong>Translation:</strong> I hope you are well.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>inti</td><td>you</td><td>Second-person singular pronoun</td></tr><tr><td>tajjeb</td><td>well; good</td><td>Masculine form; feminine form is <code>tajba</code></td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nistedinkom għall-festa ta&#39; għeluq snini nhar is-Sibt.</p><p><strong>Translation:</strong> I would like to invite you to my birthday party on Saturday.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nixtieq</td><td>I would like; I wish</td><td>Polite expression of a wish</td></tr><tr><td>nistedinkom</td><td>I invite you (plural)</td><td><code>nistieden</code> &quot;I invite&quot; + <code>-kom</code> &quot;you (plural)&quot;</td></tr><tr><td>għall-festa</td><td>to the party; for the party</td><td>Contracted <code>għal</code> + <code>il-festa</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession/category linker</td></tr><tr><td>għeluq</td><td>celebration; anniversary</td><td>In <code>għeluq snini</code>, it refers to a birthday</td></tr><tr><td>snini</td><td>my years; my age</td><td><code>snin</code> &quot;years&quot; + first-person possessive <code>-i</code></td></tr><tr><td>nhar</td><td>on the day of</td><td>Introduces a weekday or date</td></tr><tr><td>is-Sibt</td><td>Saturday</td><td>Weekday commonly used with the definite article</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Il-festa se tibda fis-sebgħa ta&#39; filgħaxija.</p><p><strong>Translation:</strong> The party will start at seven in the evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Il-festa</td><td>the party</td><td>Definite article + <code>festa</code></td></tr><tr><td>se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>tibda</td><td>it starts</td><td>Third-person feminine singular, agreeing with <code>festa</code></td></tr><tr><td>fis-sebgħa</td><td>at seven</td><td><code>f&#39;</code> + definite clock-hour form</td></tr><tr><td>ta&#39;</td><td>of; during</td><td>Connects the hour with the time of day</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Se niltaqgħu d-dar tiegħi f&#39;Valletta.</p><p><strong>Translation:</strong> We will meet at my home in Valletta.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>niltaqgħu</td><td>we meet</td><td>First-person plural form</td></tr><tr><td>d-dar</td><td>at home; the house</td><td>Common contracted spelling of <code>id-dar</code></td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr><tr><td>f&#39;Valletta</td><td>in Valletta</td><td><code>f&#39;</code> + place name; an article is usually not used</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Ikun hemm ikel, mużika u kejk.</p><p><strong>Translation:</strong> There will be food, music, and cake.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ikun</td><td>there will be; it will be</td><td>Third-person form commonly used for future existence</td></tr><tr><td>hemm</td><td>there; there is</td><td>With <code>ikun</code>, means &quot;there will be&quot;</td></tr><tr><td>ikel</td><td>food</td><td>Masculine collective noun</td></tr><tr><td>mużika</td><td>music</td><td>Feminine noun</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>kejk</td><td>cake</td><td>Masculine loanword</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Tista&#39; ġġib lil xi ħadd miegħek jekk trid.</p><p><strong>Translation:</strong> You can bring someone with you if you like.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tista&#39;</td><td>you can</td><td>Second-person singular form</td></tr><tr><td>ġġib</td><td>bring</td><td>Conjugated form of <code>ġib</code> &quot;bring&quot;</td></tr><tr><td>lil</td><td>to; marks a person as an object</td><td>Personal object marker/preposition</td></tr><tr><td>xi</td><td>some; a certain</td><td>Indefinite determiner</td></tr><tr><td>ħadd</td><td>person; anyone</td><td>With <code>xi</code>, means &quot;someone&quot;</td></tr><tr><td>miegħek</td><td>with you</td><td><code>miegħ</code> &quot;with&quot; + <code>-ek</code> &quot;you&quot;</td></tr><tr><td>jekk</td><td>if</td><td>Conjunction</td></tr><tr><td>trid</td><td>you want; you like</td><td>Second-person singular form</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok, għidli jekk ġej.</p><p><strong>Translation:</strong> Please let me know whether you are coming.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>please</td><td>Fixed polite expression</td></tr><tr><td>għidli</td><td>tell me</td><td><code>għid</code> &quot;tell&quot; + <code>-li</code> &quot;me&quot;</td></tr><tr><td>jekk</td><td>whether; if</td><td>Introduces an indirect question here</td></tr><tr><td>ġej</td><td>coming; you are coming</td><td>Masculine form; feminine form is <code>ġejja</code></td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nistenna bil-ħerqa li niċċelebraw flimkien.</p><p><strong>Translation:</strong> I look forward to celebrating together.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nistenna</td><td>I wait; I look forward</td><td>First-person singular form</td></tr><tr><td>bil-ħerqa</td><td>eagerly; with anticipation</td><td>Fixed adverbial phrase</td></tr><tr><td>li</td><td>to; introduces a clause</td><td>Conjunction</td></tr><tr><td>niċċelebraw</td><td>we celebrate</td><td>First-person plural form</td></tr><tr><td>flimkien</td><td>together</td><td>Adverb</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna</p><p><strong>Translation:</strong> Regards, Anna (email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Anna</td><td>Anna</td><td>Name</td></tr></tbody></table>',57),n=[o];function i(l,s,h,g,m,c){return e(),a("div",null,n)}const p=t(r,[["render",i]]);export{b as __pageData,p as default};
